import React, { useState } from "react";

export default function App() {
  // INPUT STATE
  const [disease, setDisease] = useState("");
  const [intent, setIntent] = useState("");
  const [location, setLocation] = useState("");

  // DATA STATE
  const [summary, setSummary] = useState("");
  const [publications, setPublications] = useState([]);
  const [clinicalTrials, setClinicalTrials] = useState([]);

  // UI STATE
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  // FILTERS
  const [showPapers, setShowPapers] = useState(true);
  const [showTrials, setShowTrials] = useState(true);
  const [yearFilter, setYearFilter] = useState("all");

  // CHAT STATE
  const [messages, setMessages] = useState([]);
  const [chatInput, setChatInput] = useState("");

  // SEARCH FUNCTION
  const handleSubmit = async () => {
    if (!disease && !intent) return;

    setLoading(true);
    setError("");

    try {
      const res = await fetch("http://localhost:8000/analyze", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ disease, intent, location }),
      });

      const data = await res.json();

      setSummary(data.summary);
      setPublications(data.publications || []);
      setClinicalTrials(data.clinical_trials || []);

      // Add to chat
      setMessages((prev) => [
        ...prev,
        { role: "user", text: `${disease} ${intent}` },
        { role: "ai", summary: data.summary }
      ]);

    } catch (err) {
      setError("Error fetching data");
    }

    setLoading(false);
  };

  // CHAT SEND
  const sendChat = async () => {
    if (!chatInput) return;

    const userMsg = { role: "user", text: chatInput };
    setMessages((prev) => [...prev, userMsg]);
    setChatInput("");

    setLoading(true);

    try {
      const res = await fetch("http://localhost:8000/analyze", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ disease: chatInput, intent: "treatment", location: "" }),
      });

      const data = await res.json();

      setMessages((prev) => [...prev, { role: "ai", summary: data.summary }]);
    } catch (e) {
      console.error(e);
    }

    setLoading(false);
  };

  // FILTER LOGIC
  const filteredPublications = publications.filter((p) => {
    if (yearFilter === "recent") return p.year >= 2020;
    return true;
  });

  return (
    <div style={{ display: "flex", height: "100vh", background: "#0B1A2B", color: "white" }}>

      {/* LEFT PANEL */}
      <div style={{ width: "300px", padding: "20px", borderRight: "1px solid #1e293b" }}>

        <h2>⚙ Filters</h2>

        <label>
          <input type="checkbox" checked={showPapers} onChange={() => setShowPapers(!showPapers)} /> Papers
        </label>
        <br />
        <label>
          <input type="checkbox" checked={showTrials} onChange={() => setShowTrials(!showTrials)} /> Trials
        </label>

        <h3 style={{ marginTop: "20px" }}>Year</h3>
        <select value={yearFilter} onChange={(e) => setYearFilter(e.target.value)}>
          <option value="all">All</option>
          <option value="recent">Last 5 years</option>
        </select>

      </div>

      {/* MAIN PANEL */}
      <div style={{ flex: 1, padding: "20px", overflowY: "auto" }}>

        {/* SEARCH */}
        <div style={{ marginBottom: "20px" }}>
          <input placeholder="Disease" value={disease} onChange={(e)=>setDisease(e.target.value)} />
          <input placeholder="Intent" value={intent} onChange={(e)=>setIntent(e.target.value)} />
          <input placeholder="Location" value={location} onChange={(e)=>setLocation(e.target.value)} />
          <button onClick={handleSubmit}>Search</button>
        </div>

        {loading && <p>Loading...</p>}
        {error && <p>{error}</p>}

        {/* SUMMARY */}
        {summary && (
          <div style={{ background: "#11263C", padding: "15px", marginBottom: "20px" }}>
            <h3>🤖 AI Summary</h3>
            <p>{summary}</p>
          </div>
        )}

        {/* PAPERS */}
        {showPapers && (
          <div>
            <h3>📄 Papers</h3>
            {filteredPublications.map((p,i)=>(
              <div key={i} style={{ background: "#11263C", marginBottom: "10px", padding: "10px" }}>
                <p>{p.title}</p>
                <small>{p.year}</small>
              </div>
            ))}
          </div>
        )}

        {/* TRIALS */}
        {showTrials && (
          <div>
            <h3>🧪 Trials</h3>
            {clinicalTrials.map((t,i)=>(
              <div key={i} style={{ background: "#11263C", marginBottom: "10px", padding: "10px" }}>
                <p>{t.title}</p>
                <small>{t.status}</small>
              </div>
            ))}
          </div>
        )}

      </div>

      {/* RIGHT PANEL CHAT */}
      <div style={{ width: "300px", borderLeft: "1px solid #1e293b", display: "flex", flexDirection: "column" }}>

        <div style={{ flex: 1, overflowY: "auto", padding: "10px" }}>
          {messages.map((m,i)=>(
            <div key={i} style={{ marginBottom: "10px" }}>
              {m.role === "user" ? (
                <div style={{ textAlign: "right" }}>{m.text}</div>
              ) : (
                <div style={{ background: "#11263C", padding: "10px" }}>{m.summary}</div>
              )}
            </div>
          ))}
        </div>

        <div style={{ padding: "10px" }}>
          <input
            value={chatInput}
            onChange={(e)=>setChatInput(e.target.value)}
            placeholder="Ask follow-up..."
            style={{ width: "70%" }}
          />
          <button onClick={sendChat}>Send</button>
        </div>

      </div>

    </div>
  );
}


const styles = {
  container: {
    minHeight: "100vh",
    padding: "40px",
    fontFamily: "Inter, Arial, sans-serif",
    background: "linear-gradient(135deg, #eef2ff 0%, #f8fafc 100%)"
  },

  heading: {
    fontSize: "42px",
    fontWeight: "800",
    textAlign: "center",
    marginBottom: "12px",
    color: "#0f172a"
  },

  subheading: {
    textAlign: "center",
    color: "#475569",
    marginBottom: "35px",
    fontSize: "18px"
  },

  searchBox: {
    display: "grid",
    gap: "12px",
    marginBottom: "30px",
    background: "rgba(255,255,255,0.7)",
    backdropFilter: "blur(12px)",
    padding: "18px",
    borderRadius: "18px",
    boxShadow: "0 8px 30px rgba(0,0,0,0.08)"
  },

  input: {
    padding: "16px",
    fontSize: "16px",
    borderRadius: "12px",
    border: "1px solid #dbeafe",
    outline: "none"
  },

  button: {
    padding: "16px 26px",
    background: "linear-gradient(135deg, #2563eb, #1d4ed8)",
    color: "white",
    border: "none",
    borderRadius: "12px",
    cursor: "pointer",
    fontWeight: "700"
  },

  pdfButton: {
    padding: "14px 24px",
    background: "linear-gradient(135deg, #16a34a, #15803d)",
    color: "white",
    border: "none",
    borderRadius: "12px",
    cursor: "pointer",
    fontWeight: "700",
    marginBottom: "30px"
  },

  summaryBox: {
    background: "white",
    padding: "24px",
    borderRadius: "18px",
    marginBottom: "30px",
    boxShadow: "0 10px 25px rgba(0,0,0,0.06)",
    borderLeft: "6px solid #2563eb"
  },

  sectionTitle: {
    marginTop: "40px",
    marginBottom: "20px",
    fontSize: "28px",
    fontWeight: "700",
    color: "#0f172a"
  },

  results: {
    display: "grid",
    gap: "22px"
  },

  card: {
    background: "white",
    padding: "26px",
    borderRadius: "18px",
    boxShadow: "0 10px 25px rgba(0,0,0,0.06)"
  },

  meta: {
    color: "#64748b",
    fontSize: "14px",
    marginBottom: "12px"
  },

  link: {
